/* @lc app=leetcode id=2326 lang=kotlin */
class Solution { fun spiralMatrix(m: Int, n: Int, head: ListNode?): Array<IntArray> = Array(m) { IntArray(n) { -1 } }.also { res -> arrayOf(head).let { h -> intArrayOf(0, m - 1, 0, n - 1).let { b -> while (h[0] != null && b[0] <= b[1] && b[2] <= b[3]) { (b[2]..b[3]).forEach { j -> h[0]?.let { node -> res[b[0]][j] = node.`val`.also { h[0] = node.next } } }.also { b[0]++ }.run { (b[0]..b[1]).forEach { i -> h[0]?.let { node -> res[i][b[3]] = node.`val`.also { h[0] = node.next } } } }.also { b[3]-- }.run { if (b[0] <= b[1]) (b[3] downTo b[2]).forEach { j -> h[0]?.let { node -> res[b[1]][j] = node.`val`.also { h[0] = node.next } } } }.also { b[1]-- }.run { if (b[2] <= b[3]) (b[1] downTo b[0]).forEach { i -> h[0]?.let { node -> res[i][b[2]] = node.`val`.also { h[0] = node.next } } } }.also { b[2]++ } } } } } }